const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const rawText = String(source.rawText || source.text || message.text || message.caption || payload.text || args.instruction || '').trim();
let spreadsheetId = String(source.spreadsheetId || source.sheetId || source.targetId || args.spreadsheetId || args.sheetId || args.targetId || payload.spreadsheetId || payload.sheetId || payload.targetId || '').trim();
let sheetName = String(source.sheetName || source.targetName || source.fileName || source.title || args.sheetName || args.targetName || args.fileName || args.title || payload.sheetName || payload.targetName || payload.fileName || payload.title || '').trim();
let sheetTab = String(source.sheetTab || args.sheetTab || payload.sheetTab || '').trim();
let range = String(source.range || source.rangeName || source.cell || args.range || args.rangeName || args.cell || payload.range || payload.rangeName || payload.cell || '').trim();
let content = source.content ?? args.content ?? payload.content ?? '';
let values = Array.isArray(source.values) ? source.values : Array.isArray(args.values) ? args.values : Array.isArray(payload.values) ? payload.values : [];

if (typeof content === 'string') {
  content = content.trim();
}
if (!content && rawText) {
  content = rawText;
}
const hasTarget = Boolean(spreadsheetId || sheetName);
return [{ json: { ...source, payload, message, chatId, rawText, spreadsheetId, targetId: spreadsheetId, sheetName, targetName: sheetName, sheetTab, range, rangeName: range, content, values, hasTarget, response: hasTarget && range ? '' : 'Mia cần tên/id sheet, phạm vi và dữ liệu mới để cập nhật.' } }];

const source = $('Prepare Action').item.json || {};
const rows = $input.all().map((item) => item.json || {}).filter((item) => item.id || item.name);
if (!rows.length) {
  return [{ json: { ...source, ok: false, response: `Mia chưa tìm thấy Google Sheet phù hợp: ${source.sheetName || source.query || ''}` } }];
}
const sheet = rows[0];
return [{ json: { ...source, ok: true, spreadsheetId: sheet.id || source.spreadsheetId || '', sheetId: sheet.id || source.sheetId || '', targetId: sheet.id || source.targetId || source.spreadsheetId || source.sheetId || '', sheetName: sheet.name || source.sheetName || source.targetName || source.query || '', targetName: sheet.name || source.targetName || source.sheetName || source.query || '', query: source.query || source.sheetName || '', webViewLink: sheet.webViewLink || source.webViewLink || '', mimeType: sheet.mimeType || source.mimeType || '', sheetTab: source.sheetTab || '' } }];

const source = $('Prepare Action').item.json || {};
function parseValues(input) {
  if (Array.isArray(input) && input.length) {
    return input;
  }
  const text = String(input || '').trim();
  if (!text) return [];
  if ((text.startsWith('[') && text.endsWith(']')) || (text.startsWith('{') && text.endsWith('}'))) {
    try {
      const parsed = JSON.parse(text);
      if (Array.isArray(parsed)) return parsed;
    } catch (err) {}
  }
  return text
    .split(/\r?\n+/)
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => line.split(/\t|,/).map((cell) => String(cell).trim()));
}

const spreadsheetId = String(source.spreadsheetId || source.sheetId || '').trim();
const sheetTab = String(source.sheetTab || '').trim();
const range = String(source.range || source.rangeName || source.cell || 'A1').trim().toUpperCase();
const values = parseValues(source.values && source.values.length ? source.values : source.content);
if (!values.length) {
  throw new Error('Missing values. Cannot update Google Sheets range with empty content.');
}
const targetRange = sheetTab ? `'${sheetTab.replace(/'/g, "''")}'!${range}` : range;
return [{ json: { ...source, spreadsheetId, targetId: source.targetId || source.spreadsheetId || source.sheetId || '', sheetId: source.sheetId || source.spreadsheetId || source.targetId || '', sheetName: source.sheetName || source.targetName || '', targetName: source.targetName || source.sheetName || '', range: targetRange, rangeName: source.rangeName || source.range || source.cell || '', values } }];

const source = $('Prepare Action').item.json || {};
const result = $json || {};
const sheetId = source.spreadsheetId || source.sheetId || source.targetId || '';
const link = source.webViewLink || (sheetId ? `https://docs.google.com/spreadsheets/d/${sheetId}/edit` : '');
const updatedRange = result.updatedRange || result.updatedData?.range || source.range || source.rangeName || '';
const shownTarget = source.targetName || source.sheetName || 'Không rõ tên';
let text = `Đã cập nhật Google Sheet: ${shownTarget}`;
if (sheetId) text += `\nID: ${sheetId}`;
text += `\nPhạm vi cập nhật: ${updatedRange}`;
if (link) text += `\nMở bảng tính: ${link}`;
return [{ json: { chatId: source.chatId || result.chatId || '', text: text.trim(), spreadsheetId: sheetId, webViewLink: link } }];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target = source.subject || source.sender || source.query || source.messageId || source.id || '';
let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false || source.isReady === false ? 'missing_required_input' : 'not_found_or_not_applicable'
    }
  }
}];
